'use strict';
const $=s=>document.querySelector(s),params=new URLSearchParams(location.search);let lang=params.get('lang')==='ru'?'ru':'en';try{if(!params.has('lang'))lang=localStorage.getItem('portfolio-language')==='ru'?'ru':'en';}catch{}
let project=null;
const localized=value=>value?.[lang]||value?.en||value?.ru||'';
function videoEmbed(value){if(!value)return null;const url=new URL(value);if(['youtube.com','www.youtube.com'].includes(url.hostname)){const id=url.searchParams.get('v')||url.pathname.split('/').filter(Boolean).pop();if(/^[a-zA-Z0-9_-]{11}$/.test(id))return `https://www.youtube-nocookie.com/embed/${id}`;}if(url.hostname==='youtu.be'){const id=url.pathname.slice(1);if(/^[a-zA-Z0-9_-]{11}$/.test(id))return `https://www.youtube-nocookie.com/embed/${id}`;}if(['vimeo.com','www.vimeo.com'].includes(url.hostname)){const id=url.pathname.split('/').filter(Boolean).find(x=>/^\d+$/.test(x));if(id)return `https://player.vimeo.com/video/${id}`;}return null;}
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));$('#back-link').textContent=lang==='ru'?'← Все работы':'← All projects';if(!project)return;$('#work-result').hidden=false;$('#work-status').textContent=params.has('preview')?(lang==='ru'?'Предпросмотр сохранённой версии · только для владельца':'Saved preview · owner only'):'';$('#work-category').textContent=project.category.toUpperCase()+(project.concept?(lang==='ru'?' / КОНЦЕПЦИЯ':' / CONCEPT'):'');$('#work-title').textContent=localized(project.title);document.title=`${localized(project.title)} — QWELSKW`;$('#work-description').textContent=localized(project.description);document.querySelector('meta[name="description"]').content=localized(project.description);$('#work-cover').src=project.cover;$('#work-cover').alt=localized(project.title);$('#work-cover').hidden=!project.cover;$('#work-text').textContent=localized(project.result);$('#work-tech').textContent=project.tech;$('#work-gallery').replaceChildren(...project.gallery.map((src,i)=>{const img=document.createElement('img');img.src=src;img.alt=`${localized(project.title)} — ${i+1}`;img.loading='lazy';return img;}));const video=$('#work-video');video.replaceChildren();if(project.video){const embed=videoEmbed(project.video);if(embed){const frame=document.createElement('iframe');frame.src=embed;frame.title=localized(project.title);frame.allow='fullscreen; picture-in-picture';frame.allowFullscreen=true;frame.loading='lazy';video.append(frame);}const link=document.createElement('a');link.href=project.video;link.target='_blank';link.rel='noopener noreferrer';link.textContent=lang==='ru'?'Открыть видео ↗':'Open video ↗';video.append(link);}$('#work-link').hidden=!project.link;$('#work-link').href=project.link||'#';$('#work-link').textContent=lang==='ru'?'Открыть сайт ↗':'View website ↗';}
document.querySelectorAll('[data-lang]').forEach(button=>button.onclick=()=>{lang=button.dataset.lang;try{localStorage.setItem('portfolio-language',lang);}catch{}render();});
(async()=>{try{const id=params.get('id');if(!id)throw new Error();if(params.has('preview')){project=await portfolioAPI(`/api/admin/projects/${encodeURIComponent(id)}`);}else{project=(await portfolioAPI('/api/content')).projects.find(p=>p.id===id);}if(!project)throw new Error();render();}catch{$('#work-status').textContent=lang==='ru'?'Работа не найдена или недоступна.':'This project is unavailable.';}})();render();
